package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;

/**
 * Email is optional. When absent (null or blank) the owner is left unchanged. When present it
 * must be a syntactically valid address; the validated {@link OwnerFieldsDto} is mutated in place
 * so the stored and returned value is lower-cased, or {@link InvalidEmailException} is thrown for a
 * 400 when the address is not syntactically valid.
 */
public class NormalizeOwnerEmail {

    /**
     * Single-{@code @} address with non-empty, whitespace-free local and domain parts and at least
     * one dot in the domain (e.g. {@code user@example.com}). Sufficient to reject values such as
     * {@code not-an-email} while accepting ordinary addresses.
     */
    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");

    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
        String email = request.getEmail();
        if (email == null || email.isBlank()) {
            return;
        }
        String trimmed = email.trim();
        if (!EMAIL.matcher(trimmed).matches()) {
            throw new InvalidEmailException(email);
        }
        request.setEmail(trimmed.toLowerCase(Locale.ROOT));
    }
}
===== RejectDisposableEmailDomain.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Set;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DisposableEmailDomainException;

/**
 * Rejects an owner whose email uses a disposable-domain provider. Runs after
 * {@link NormalizeOwnerEmail}, so the address has already been validated and lower-cased. Email is
 * optional: when absent (null or blank) the owner is left unchanged. When the domain is on the
 * blocklist a {@link DisposableEmailDomainException} is thrown for a 400.
 */
public class RejectDisposableEmailDomain {

    private static final Set<String> BLOCKED_DOMAINS =
            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");

    public void service(@Val OwnerFieldsDto request) throws DisposableEmailDomainException {
        String email = request.getEmail();
        if (email == null || email.isBlank()) {
            return;
        }
        int at = email.lastIndexOf('@');
        if (at < 0) {
            return;
        }
        String domain = email.substring(at + 1).trim().toLowerCase(Locale.ROOT);
        if (BLOCKED_DOMAINS.contains(domain)) {
            throw new DisposableEmailDomainException(domain);
        }
    }
}
===== CheckOwnerCityCapacity.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;

/**
 * Rejects a create-owner request when the request's city already contains 50 or more owners,
 * throwing {@link CityAtCapacityException} for a 409. The city is compared case-insensitively
 * (matching {@link AssignCustomerCode}'s per-city counting). Runs before the owner is saved, so the
 * count excludes the owner being created.
 */
public class CheckOwnerCityCapacity {

    private static final int CAPACITY = 50;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws CityAtCapacityException {
        String city = request.getCity();
        long count = ownerRepository.findAll().stream()
                .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
                .count();
        if (count >= CAPACITY) {
            throw new CityAtCapacityException(city);
        }
    }
}
===== CheckOwnerDailyLimit.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitException;
import org.springframework.samples.petclinic.rest.function.common.BusinessDays;

/**
 * Rejects a create-owner request once 100 or more owners have already been created for the same
 * business day, throwing {@link DailyOwnerLimitException} for a 429. The day counted is the
 * request's effective, business-day-adjusted {@code registrationDate} (the supplied date or, when
 * omitted, the server date, with any weekend rolled forward to Monday) — the same date
 * {@link BuildOwner} stamps on the new owner. Runs before the owner is saved, so the count excludes
 * the owner being created: the 100th owner of the day is accepted, the 101st is rejected.
 */
public class CheckOwnerDailyLimit {

    private static final int DAILY_LIMIT = 100;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DailyOwnerLimitException {
        LocalDate supplied = request.getRegistrationDate();
        LocalDate effective = BusinessDays.rollToBusinessDay(supplied != null ? supplied : LocalDate.now());
        long count = ownerRepository.findAll().stream()
                .filter(existing -> effective.equals(existing.getRegistrationDate()))
                .count();
        if (count >= DAILY_LIMIT) {
            throw new DailyOwnerLimitException();
        }
    }
}
===== BuildOwner.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.function.common.BusinessDays;

public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
        Owner owner = ownerMapper.toOwner(request);
        LocalDate effective = owner.getRegistrationDate() != null
                ? owner.getRegistrationDate()
                : LocalDate.now();
        owner.setRegistrationDate(BusinessDays.rollToBusinessDay(effective));
        built.set(owner);
    }
}

